insert into public.categories (id, name, slug, description, image_url, image_alt, parent_id, sort_order, seo_title, seo_description, seo_keywords)
values
  ('eed6f449-6253-5989-bb7d-291a52721012', 'Curtains & Drapes', 'curtains-and-drapes', 'Floor-to-ceiling drapes, sheer layers and blackout curtains tailored for villas, apartments and commercial interiors across Dubai and Abu Dhabi.', 'https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=1600&q=80', 'Ivory living room drapes in a Dubai villa', null, 1, 'Custom Curtains & Drapes in Dubai & Abu Dhabi | Maison Drape', 'Bespoke curtains and drapes with blackout linings, sheers and designer fabrics. Free in-home measuring in Dubai and Abu Dhabi.', 'custom curtains Dubai, blackout drapes Dubai, sheer curtains UAE, pinch pleat curtains, S-wave drapes'),
  ('357b6c7b-fa42-5f49-abc2-68a1dcec5420', 'Blinds & Shades', 'blinds-and-shades', 'Roller, zebra, roman and Venetian blinds engineered for UAE heat, glare control and effortless daily use.', 'https://images.unsplash.com/photo-1560185007-cde436f6a4d0?auto=format&fit=crop&w=1600&q=80', 'Modern roller blinds in a bright apartment', null, 2, 'Blinds & Shades Dubai | Roller, Zebra, Roman | Maison Drape', 'Heat-ready roller, zebra, roman and Venetian blinds with blackout and sunscreen fabrics. Same-week installation across the UAE.', 'roller blinds Dubai, zebra blinds UAE, roman shades Abu Dhabi, sunscreen blinds, blackout blinds Dubai'),
  ('5d2db8ee-97f8-5418-8b81-ff0082d646ab', 'Motorized', 'motorized', 'Quiet motorised tracks and blinds with smart-home integration for Lutron, Control4, Apple Home and Google Home.', 'https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=1600&q=80', 'Motorized curtain track in a luxury penthouse', null, 3, 'Motorized Curtains & Blinds UAE | Smart Home Ready', 'Silent motorised curtains and blinds with smart-home pairing. Professional installation in Dubai and Abu Dhabi.', 'motorized curtains Dubai, motorised tracks UAE, smart blinds Dubai, Lutron curtains, battery roller motors')
insert into public.products (id, category_id, name, slug, description, base_price, images, fabric_options, is_bestseller, is_active, seo_title, seo_description, seo_keywords, created_at)
values
  ('6de7d6e6-1bdc-5054-8861-5dbb9900bae6', 'eed6f449-6253-5989-bb7d-291a52721012', 'Belgian Linen Pinch-Pleat Drape', 'belgian-linen-pinch-pleat-drape', 'Full-bodied Belgian linen with a classic pinch pleat, cotton sateen lining and optional blackout interlining. Tailored to your exact drop, with hand-finished headings and weighted hems that fall cleanly in UAE villas.', 890, '[{"url":"https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=1600&q=80","alt":"Belgian linen pinch-pleat drapes in a living room","thumbnailUrl":"https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=400&q=80"},{"url":"https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=1600&q=80","alt":"Close-up of linen curtain fabric and heading","thumbnailUrl":"https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=400&q=80"},{"url":"https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=1600&q=80","alt":"Linen drapes framing a villa window","thumbnailUrl":"https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=400&q=80"}]'::jsonb, '["Natural flax","Sand","Stone grey","Ivory"]'::jsonb, true, true, 'Belgian Linen Pinch-Pleat Drapes Dubai | From AED 890', 'Custom Belgian linen pinch-pleat drapes with blackout lining. Free measuring visit in Dubai and Abu Dhabi.', 'Belgian linen curtains Dubai, pinch pleat drapes UAE, linen blackout curtains, villa curtains Dubai', '2026-01-12T00:00:00.000Z'),
  ('f2d60ffb-41b2-58aa-8ee0-05602af56f37', 'eed6f449-6253-5989-bb7d-291a52721012', 'S-Wave Sheer Voile', 's-wave-sheer-voile', 'Soft S-fold sheers that diffuse Gulf sunlight without losing the view. Available in washable polyester voile or silk-blend, on discreet ceiling or wall tracks.', 420, '[{"url":"https://images.unsplash.com/photo-1600210492493-0946911123ea?auto=format&fit=crop&w=1600&q=80","alt":"Sheer voile curtains in a bright bedroom","thumbnailUrl":"https://images.unsplash.com/photo-1600210492493-0946911123ea?auto=format&fit=crop&w=400&q=80"},{"url":"https://images.unsplash.com/photo-1616594039964-ae9021a400a0?auto=format&fit=crop&w=1600&q=80","alt":"Layered sheers and drapes","thumbnailUrl":"https://images.unsplash.com/photo-1616594039964-ae9021a400a0?auto=format&fit=crop&w=400&q=80"}]'::jsonb, '["Cloud white","Warm ivory","Pale taupe"]'::jsonb, true, true, 'S-Wave Sheer Curtains Dubai | Light-Filtering Voile', 'S-fold sheer voile curtains for villas and apartments. Pair with blackout drapes. From AED 420.', 'sheer curtains Dubai, S-wave voile, light filtering curtains UAE, wave fold sheers', '2026-02-02T00:00:00.000Z'),
  ('345558bc-ba74-59a3-a778-17329e2fd59b', 'eed6f449-6253-5989-bb7d-291a52721012', 'Triple-Weave Blackout Drape', 'triple-weave-blackout-drape', 'Hotel-grade triple-weave blackout that blocks heat and light for bedrooms, media rooms and nurseries. No bulky lining required, with a clean contemporary fall.', 560, '[{"url":"https://images.unsplash.com/photo-1616046229478-9901c5536a45?auto=format&fit=crop&w=1600&q=80","alt":"Blackout bedroom curtains","thumbnailUrl":"https://images.unsplash.com/photo-1616046229478-9901c5536a45?auto=format&fit=crop&w=400&q=80"},{"url":"https://images.unsplash.com/photo-1505693416388-ac5ce068fe85?auto=format&fit=crop&w=1600&q=80","alt":"Dark drapes in a modern bedroom","thumbnailUrl":"https://images.unsplash.com/photo-1505693416388-ac5ce068fe85?auto=format&fit=crop&w=400&q=80"}]'::jsonb, '["Charcoal","Navy","Taupe","Cream"]'::jsonb, false, true, 'Blackout Curtains Dubai | Triple-Weave Heat Control', 'Triple-weave blackout drapes for UAE bedrooms. Heat and glare control with a tailored finish. From AED 560.', 'blackout curtains Dubai, bedroom blackout drapes, heat control curtains UAE, triple weave blackout', '2026-03-08T00:00:00.000Z'),
  ('88236b8c-7c9f-5874-8229-eafe2f20f6ff', '357b6c7b-fa42-5f49-abc2-68a1dcec5420', 'Solar Sunscreen Roller Blind', 'solar-sunscreen-roller-blind', 'Openness-factor 5% sunscreen mesh that cuts glare and UV while keeping the skyline. Cassette or open-roll hardware, child-safe chain or motor.', 380, '[{"url":"https://images.unsplash.com/photo-1560185007-cde436f6a4d0?auto=format&fit=crop&w=1600&q=80","alt":"Sunscreen roller blinds in a living room","thumbnailUrl":"https://images.unsplash.com/photo-1560185007-cde436f6a4d0?auto=format&fit=crop&w=400&q=80"},{"url":"https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1600&q=80","alt":"Floor-to-ceiling roller blinds","thumbnailUrl":"https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=400&q=80"}]'::jsonb, '["Pearl","Greige","Graphite"]'::jsonb, true, true, 'Sunscreen Roller Blinds Dubai | UV & Glare Control', 'Solar sunscreen roller blinds for UAE apartments and offices. UV protection with a view. From AED 380.', 'sunscreen roller blinds Dubai, UV blinds UAE, solar mesh blinds, glare control blinds', '2026-01-20T00:00:00.000Z'),
  ('25ba0a5a-a8ac-51f7-94ba-cd554bdfab18', '357b6c7b-fa42-5f49-abc2-68a1dcec5420', 'Dual-Layer Zebra Blind', 'dual-layer-zebra-blind', 'Alternating sheer and opaque bands for instant privacy or daylight. Popular in kitchens, studies and rental apartments that need a polished, low-maintenance finish.', 340, '[{"url":"https://images.unsplash.com/photo-1595526114035-0d45ed16cfbf?auto=format&fit=crop&w=1600&q=80","alt":"Zebra blinds in a modern kitchen","thumbnailUrl":"https://images.unsplash.com/photo-1595526114035-0d45ed16cfbf?auto=format&fit=crop&w=400&q=80"},{"url":"https://images.unsplash.com/photo-1556912173-3bb406ef7e77?auto=format&fit=crop&w=1600&q=80","alt":"Striped dual-layer window blinds","thumbnailUrl":"https://images.unsplash.com/photo-1556912173-3bb406ef7e77?auto=format&fit=crop&w=400&q=80"}]'::jsonb, '["White","Beige","Grey"]'::jsonb, true, true, 'Zebra Blinds Dubai | Dual-Layer Day & Night Shades', 'Dual-layer zebra blinds with day and night control. Fast installation in Dubai and Abu Dhabi. From AED 340.', 'zebra blinds Dubai, day night blinds UAE, dual layer shades, kitchen zebra blinds', '2026-02-18T00:00:00.000Z'),
  ('22606548-d81e-5efa-aea6-f83e30338076', '357b6c7b-fa42-5f49-abc2-68a1dcec5420', 'Soft-Fold Roman Shade', 'soft-fold-roman-shade', 'Tailored roman shades with even, architectural folds. Choose linen, cotton or blackout interlining for bedrooms that need both softness and sleep quality.', 640, '[{"url":"https://images.unsplash.com/photo-1615874959474-d453134d8ba8?auto=format&fit=crop&w=1600&q=80","alt":"Roman shades in a bedroom","thumbnailUrl":"https://images.unsplash.com/photo-1615874959474-d453134d8ba8?auto=format&fit=crop&w=400&q=80"},{"url":"https://images.unsplash.com/photo-1618220179428-22790b461013?auto=format&fit=crop&w=1600&q=80","alt":"Fabric roman blind close-up","thumbnailUrl":"https://images.unsplash.com/photo-1618220179428-22790b461013?auto=format&fit=crop&w=400&q=80"}]'::jsonb, '["Linen oatmeal","Cotton sage","Velvet moss"]'::jsonb, false, true, 'Roman Shades Dubai | Soft-Fold Custom Fabric Blinds', 'Custom roman shades with blackout options. Soft folds, precise stacking. From AED 640 in the UAE.', 'roman shades Dubai, fabric roman blinds UAE, blackout roman shade, bedroom roman blinds', '2026-04-01T00:00:00.000Z'),
  ('f107b3b2-4097-5f24-8e05-37eef89bc39a', '5d2db8ee-97f8-5418-8b81-ff0082d646ab', 'Silent Motorised Curtain Track', 'silent-motorised-curtain-track', 'Ultra-quiet tubular motor on a curved or straight aluminium track. Pair with any Maison drape, control via wall switch, remote, or smart home.', 1450, '[{"url":"https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=1600&q=80","alt":"Motorized curtain track in a penthouse","thumbnailUrl":"https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=400&q=80"},{"url":"https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?auto=format&fit=crop&w=1600&q=80","alt":"Smart living room with automated drapes","thumbnailUrl":"https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?auto=format&fit=crop&w=400&q=80"}]'::jsonb, '["Works with all Maison fabrics"]'::jsonb, true, true, 'Motorized Curtain Tracks Dubai | Silent Smart Home', 'Silent motorised curtain tracks with smart-home integration. Professional fitting in Dubai and Abu Dhabi. From AED 1,450.', 'motorized curtain track Dubai, silent curtain motor UAE, smart home drapes, Lutron curtain track', '2026-03-15T00:00:00.000Z'),
  ('b6ad8e49-92c1-5eeb-90d5-843c0748cf75', '5d2db8ee-97f8-5418-8b81-ff0082d646ab', 'Battery Motor Roller Blind', 'battery-motor-roller-blind', 'Wire-free rechargeable motor roller — ideal for finished apartments where chasing cables is not an option. Solar charging optional on south-facing glass.', 980, '[{"url":"https://images.unsplash.com/photo-1600585154526-990dced4db0d?auto=format&fit=crop&w=1600&q=80","alt":"Motorized roller blinds on large glass","thumbnailUrl":"https://images.unsplash.com/photo-1600585154526-990dced4db0d?auto=format&fit=crop&w=400&q=80"},{"url":"https://images.unsplash.com/photo-1600607687644-c7171b42498b?auto=format&fit=crop&w=1600&q=80","alt":"Automated blinds in a contemporary home","thumbnailUrl":"https://images.unsplash.com/photo-1600607687644-c7171b42498b?auto=format&fit=crop&w=400&q=80"}]'::jsonb, '["Sunscreen 5%","Blackout","Dim-out"]'::jsonb, false, true, 'Battery Motor Roller Blinds UAE | Wire-Free Automation', 'Rechargeable motorised roller blinds without electrical chasing. Smart control. From AED 980.', 'battery motor roller blinds Dubai, wire free blinds UAE, rechargeable roller motor, solar roller blinds', '2026-04-12T00:00:00.000Z')
