insert into public.testimonials (id, customer_name, rating, review_text, source, is_featured, created_at)
values
  ('6f2e8fe2-c714-5b71-bdb0-9e9704023906', 'Layla Al Maktoum', 5, 'The team measured our Palm villa in a single visit and installed motorised linen drapes that actually stay quiet at night. Finish quality is hotel-level.', 'Google', true, '2026-05-02T00:00:00.000Z'),
  ('1efdca17-324e-5071-b7af-0661070641fc', 'James Whitaker', 5, 'We needed blackout for a Marina apartment nursery. Same-week visit, precise fit on tricky sliding doors, and they cleaned up every pin.', 'Google', true, '2026-06-11T00:00:00.000Z'),
  ('1e064c11-fd9b-5318-9433-5720eca0fb1c', 'Noura Hassan', 5, 'Trade pricing for our interior studio has been consistent, and the S-wave sheers photograph beautifully for client presentations.', 'Houzz', true, '2026-07-19T00:00:00.000Z'),
  ('eb7bc3df-87cd-51dc-9194-06e07e504771', 'Omar Farouk', 4, 'Zebra blinds in the kitchen and sunscreen rollers in the living room. Good advice on fabrics that can handle Abu Dhabi afternoon sun.', 'Google', true, '2026-08-03T00:00:00.000Z')
