insert into public.faqs (id, question, answer, category, sort_order)
values
  ('de70fafa-9ff8-5d49-830e-0f23e890c58f', 'Do you offer a free in-home measuring visit?', 'Yes. We offer a complimentary measuring visit across Dubai and Abu Dhabi. A consultant brings fabric books, discusses blackout and motorisation, and leaves you with a written estimate.', 'visits', 1),
  ('c0ba28e4-00bf-50bf-81e4-9089839865a5', 'How long does made-to-measure take?', 'Standard curtains and blinds are typically 7–12 working days after fabric confirmation. Motorised tracks and imported designer textiles can take 14–21 days. We confirm lead times on every quote.', 'orders', 2),
  ('5cd69860-08e0-559b-9f10-deeb007a6b38', 'Are your fabrics suitable for UAE heat and sun?', 'We specify UV-stable weaves, sunscreen meshes and blackout interlinings tested for Gulf glare. South and west elevations are always quoted with heat-control options.', 'products', 3),
  ('98546d60-9b6d-5db5-9401-fca529f12482', 'Can you integrate with existing smart home systems?', 'Yes. Our motors pair with Lutron, Control4, Apple Home, Google Home and most RF remotes. We coordinate with your systems integrator when needed.', 'motorized', 4),
  ('d7d545ce-e568-52a2-bb39-a474965330da', 'What warranty do you provide?', 'Every installation includes a 12-month workmanship warranty. Motors carry the manufacturer warranty of 3–5 years depending on the range.', 'orders', 5),
  ('26e4776c-b4aa-5577-b2a9-350e9c88987e', 'Do you work with interior designers and developers?', 'Yes. Our trade programme offers project pricing, sample libraries and dedicated account support. Apply on the Partnerships page.', 'trade', 6)
insert into public.blog_posts (id, title, slug, excerpt, content, cover_image_url, cover_image_alt, author, published_at, seo_title, seo_description, seo_keywords)
values
  ('789e93f4-0952-51a4-a8ca-aca313aaad5f', 'How to choose blackout curtains for Dubai bedrooms', 'blackout-curtains-dubai-bedrooms', 'Not all blackout is equal in 45-degree summers. Here is how lining, weave and track type change sleep quality in UAE apartments.', '<p>Dubai bedrooms fight two problems at once: late sunsets over west-facing glass and HVAC that works harder when fabric cannot stop radiant heat. A cheap coated lining often cracks within a season. A triple-weave or a proper interlined drape does not.</p>
insert into public.cms_pages (slug, title, content, seo_title, seo_description)
values
  ('privacy-policy', 'Privacy Policy', '<p>Maison Drape ("we") collects contact details you submit on estimate and booking forms, plus technical cookies required to run this site. We use that information only to respond to your enquiry, schedule visits and improve our service.</p>
